INSERT INTO `api_plan` (`id`, `api_plan`) VALUES
(1, '&lt;!-- FAQ Area Start --&gt;\n&lt;div id=&quot;faq&quot;&gt;\n	&lt;div class=&quot;container&quot;&gt;\n		&lt;!-- FAQ Categories Start --&gt;\n		&lt;div class=&quot;col-md-3 faq-categories&quot;&gt;\n			&lt;h3&gt;\n				API DOCUMENT&lt;/h3&gt;\n			&lt;ul class=&quot;nav&quot; role=&quot;tablist&quot;&gt;\n				&lt;li class=&quot;active&quot; role=&quot;presentation&quot;&gt;\n					&lt;a aria-controls=&quot;sharedTab&quot; data-toggle=&quot;tab&quot; href=&quot;#recharge&quot; role=&quot;tab&quot;&gt;Recharge API&lt;/a&gt;&lt;/li&gt;\n				&lt;li role=&quot;presentation&quot;&gt;\n					&lt;a aria-controls=&quot;vpsTab&quot; data-toggle=&quot;tab&quot; href=&quot;#dmr&quot; role=&quot;tab&quot;&gt;Money Transfer API&lt;/a&gt;&lt;/li&gt;\n			&lt;/ul&gt;\n		&lt;/div&gt;\n		&lt;!-- FAQ Categories End --&gt;&lt;!-- FAQ Content Start --&gt;\n		&lt;div class=&quot;col-md-9 faq-content&quot;&gt;\n			&lt;div class=&quot;tab-content&quot;&gt;\n				&lt;div class=&quot;tab-pane fade in active&quot; id=&quot;recharge&quot; role=&quot;tabpanel&quot;&gt;\n					&lt;div class=&quot;panel-group accordion&quot; id=&quot;accordion1&quot; role=&quot;tablist&quot;&gt;\n						&lt;!-- Accordion Item Start --&gt;\n						&lt;div class=&quot;panel panel-default active&quot;&gt;\n							&lt;div class=&quot;panel-heading&quot; role=&quot;tab&quot;&gt;\n								&lt;h4 class=&quot;panel-title&quot;&gt;\n									&lt;a data-parent=&quot;#accordion1&quot; data-toggle=&quot;collapse&quot; href=&quot;#sharedTabQ1&quot; role=&quot;button&quot;&gt;Mobile Recharge API Document&lt;/a&gt;&lt;/h4&gt;\n							&lt;/div&gt;\n							&lt;div class=&quot;panel-collapse collapse in&quot; id=&quot;sharedTabQ1&quot; role=&quot;tabpanel&quot;&gt;\n								&lt;div class=&quot;panel-body&quot;&gt;\n									&lt;div class=&quot;table-responsive&quot;&gt;\n										&lt;h1&gt;\n											API For Mobile, DTH, Postpaid Recharge&lt;/h1&gt;\n										&lt;div class=&quot;alert alert-info&quot;&gt;\n											&lt;strong&gt;Recharge API&lt;/strong&gt; .&lt;/div&gt;\n										&lt;p&gt;\n											Send a GET/POST request to&lt;/p&gt;\n										&lt;p&gt;\n											http://myrc.in/recharge/api?username=[Value]&amp;amp;pwd=[Value]&amp;amp;circlecode=[Value]&amp;amp;operatorcode=[Value]&amp;amp;number=[Value]&amp;amp;amount=[Value]&amp;amp;orderid=[Value]&amp;amp;format=[Value]&lt;br /&gt;\n											&amp;nbsp;&lt;/p&gt;\n										&lt;p&gt;\n											&lt;em&gt;eg.&lt;/em&gt;&lt;span style=&quot;color:#222222; font-family:Arial,Verdana,sans-serif; font-size:12px&quot;&gt;http://myrc.in/recharge/api?username=500011&amp;amp;pwd=123&amp;amp;circlecode=2&amp;amp;operatorcode=A&amp;amp;number=980000000&amp;amp;amount=10&amp;amp;orderid=485668&amp;amp;format=json&lt;/span&gt;&lt;/p&gt;\n										&lt;p&gt;\n											&amp;nbsp;&lt;/p&gt;\n										&lt;p&gt;\n											&lt;span style=&quot;color:#222222&quot;&gt;Whenever you submit or enquire any request through our API&amp;#39;s the system immediately gives you the response in any one of the following three different formats:&lt;/span&gt;&lt;/p&gt;\n										&lt;div&gt;\n											Comma separated format(&lt;strong&gt;csv&lt;/strong&gt;) &amp;ndash; Default Response&lt;/div&gt;\n										&lt;div&gt;\n											&lt;strong&gt;json &lt;/strong&gt;Format&lt;/div&gt;\n										&lt;div&gt;\n											&lt;strong&gt;xml &lt;/strong&gt;Format&lt;/div&gt;\n										&lt;p&gt;\n											&lt;strong&gt;Sample CSV Response&lt;/strong&gt;&lt;/p&gt;\n										&lt;p&gt;\n											1225,Success,WB22565584,980000000,10,485668&lt;/p&gt;\n										&lt;table class=&quot;table table-bordered&quot;&gt;\n											&lt;thead&gt;\n												&lt;tr&gt;\n													&lt;th scope=&quot;col&quot;&gt;\n														Position&lt;/th&gt;\n													&lt;th scope=&quot;col&quot;&gt;\n														Parameter&lt;/th&gt;\n													&lt;th scope=&quot;col&quot;&gt;\n														Details&lt;/th&gt;\n												&lt;/tr&gt;\n											&lt;/thead&gt;\n											&lt;tbody&gt;\n												&lt;tr&gt;\n													&lt;td&gt;\n														0&lt;/td&gt;\n													&lt;td&gt;\n														txid&lt;/td&gt;\n													&lt;td&gt;\n														Transaction id of every recharge request&amp;nbsp;&lt;/td&gt;\n												&lt;/tr&gt;\n												&lt;tr&gt;\n													&lt;td&gt;\n														1&lt;/td&gt;\n													&lt;td&gt;\n														status&lt;/td&gt;\n													&lt;td&gt;\n														It is status&amp;nbsp;&lt;/td&gt;\n												&lt;/tr&gt;\n												&lt;tr&gt;\n													&lt;td&gt;\n														2&lt;/td&gt;\n													&lt;td&gt;\n														opid&lt;/td&gt;\n													&lt;td&gt;\n														It is Operator id from operaor end&lt;/td&gt;\n												&lt;/tr&gt;\n												&lt;tr&gt;\n													&lt;td&gt;\n														3&lt;/td&gt;\n													&lt;td&gt;\n														number&lt;/td&gt;\n													&lt;td&gt;\n														It is recharge number&amp;nbsp;&lt;/td&gt;\n												&lt;/tr&gt;\n												&lt;tr&gt;\n													&lt;td&gt;\n														4&lt;/td&gt;\n													&lt;td&gt;\n														amount&lt;/td&gt;\n													&lt;td&gt;\n														It is amount&lt;/td&gt;\n												&lt;/tr&gt;\n												&lt;tr&gt;\n													&lt;td&gt;\n														5&lt;/td&gt;\n													&lt;td&gt;\n														orderid&lt;/td&gt;\n													&lt;td&gt;\n														It is your unique order id ,&amp;nbsp;&lt;/td&gt;\n												&lt;/tr&gt;\n											&lt;/tbody&gt;\n										&lt;/table&gt;\n										&lt;div&gt;\n											&amp;nbsp;&lt;/div&gt;\n										&lt;div&gt;\n											&lt;strong&gt;JSON Format&lt;/strong&gt;&lt;/div&gt;\n										&lt;div&gt;\n											&amp;nbsp;&lt;/div&gt;\n										&lt;div&gt;\n											To get the response in JSON format, you need to pass the parameter &amp;#39;format=json&amp;#39;&lt;/div&gt;\n										&lt;div&gt;\n											Sample JSON Response&lt;/div&gt;\n										&lt;div&gt;\n											&amp;nbsp;&lt;/div&gt;\n										&lt;div&gt;\n											{&amp;quot;txid&amp;quot;:&amp;quot;5804&amp;quot;,&amp;quot;status&amp;quot;:&amp;quot;Success&amp;quot;,&amp;quot;opid&amp;quot;:&amp;quot;RJ0317161622000269New&amp;quot;,&amp;quot;number&amp;quot;:&amp;quot;980000000&amp;quot;,&amp;quot;amount&amp;quot;:&amp;quot;10&amp;quot;,&amp;quot;orderid&amp;quot;:&amp;quot;485668&amp;quot;}&lt;/div&gt;\n										&lt;div&gt;\n											&amp;nbsp;&lt;/div&gt;\n										&lt;div&gt;\n											&lt;strong&gt;XML Format&lt;/strong&gt;&lt;/div&gt;\n										&lt;div&gt;\n											&amp;nbsp;&lt;/div&gt;\n										&lt;div&gt;\n											Pass &amp;#39;format=xml&amp;#39; in your API call to see the XML format response.&lt;/div&gt;\n										&lt;div&gt;\n											Sample XML Response&lt;/div&gt;\n										&lt;div&gt;\n											&amp;nbsp;&lt;/div&gt;\n										&lt;div&gt;\n											&lt;div&gt;\n												&amp;nbsp;&lt;/div&gt;\n											&lt;div&gt;\n												&lt;!--?xml version=&quot;1.0&quot; ?--&gt;&lt;/div&gt;\n											&lt;div&gt;\n												&amp;nbsp;&lt;/div&gt;\n											&lt;div&gt;\n												&amp;nbsp; &amp;quot;&lt;/div&gt;\n											&lt;div&gt;\n												5804&lt;/div&gt;\n											&lt;div&gt;\n												Success&lt;/div&gt;\n											&lt;div&gt;\n												RJ0317161622000269New&lt;/div&gt;\n											&lt;div&gt;\n												980000000&lt;/div&gt;\n											&lt;div&gt;\n												10&lt;/div&gt;\n											&lt;div&gt;\n												485668&lt;/div&gt;\n											&lt;div&gt;\n												&amp;quot;&lt;/div&gt;\n											&lt;div&gt;\n												&amp;nbsp;&lt;/div&gt;\n										&lt;/div&gt;\n										&lt;div class=&quot;alert alert-info&quot;&gt;\n											&lt;strong&gt;Balance API&lt;/strong&gt;&lt;/div&gt;\n										&lt;p&gt;\n											Send a GET/POST request to&lt;/p&gt;\n										&lt;p&gt;\n											http://myrc.in/recharge/balance?username=[Value]&amp;amp;pwd=[Value]&lt;br /&gt;\n											&amp;nbsp;&lt;/p&gt;\n										&lt;p&gt;\n											&lt;em&gt;eg.&lt;/em&gt;&lt;span style=&quot;color:#222222; font-family:Arial,Verdana,sans-serif; font-size:12px&quot;&gt;http://myrc.in/recharge/balance?username=500011&amp;amp;pwd=123&lt;/span&gt;&lt;/p&gt;\n										&lt;p&gt;\n											&amp;nbsp;&lt;/p&gt;\n										&lt;div class=&quot;alert alert-info&quot;&gt;\n											&lt;strong&gt;Status API&lt;/strong&gt;&lt;/div&gt;\n										&lt;p&gt;\n											Send a GET/POST request to&lt;/p&gt;\n										&lt;p&gt;\n											http://myrc.in/recharge/status?username=[Value]&amp;amp;pwd=[Value]&amp;amp;orderid=[Value]&amp;amp;format=[Value]&lt;br /&gt;\n											&amp;nbsp;&lt;/p&gt;\n										&lt;p&gt;\n											&lt;em&gt;eg.&lt;/em&gt;&lt;span style=&quot;color:#222222; font-family:Arial,Verdana,sans-serif; font-size:12px&quot;&gt;http://myrc.in/recharge/status?username=500011&amp;amp;pwd=123&amp;amp;orderid=485668&amp;amp;format=json&lt;/span&gt;&lt;/p&gt;\n										&lt;p&gt;\n											&amp;nbsp;&lt;/p&gt;\n										&lt;div&gt;\n											&lt;div class=&quot;alert alert-info&quot;&gt;\n												&lt;strong&gt;Complain API&lt;/strong&gt;&lt;/div&gt;\n											&lt;p&gt;\n												Send a GET/POST request to&lt;/p&gt;\n											&lt;p&gt;\n												http://myrc.in/recharge/complain?username=[Value]&amp;amp;pwd=[Value]&amp;amp;mobile=[Value]&amp;amp;amount=[Value]&amp;amp;txid=[Value]&amp;amp;message=[Value]&lt;/p&gt;\n											&lt;p&gt;\n												&lt;em&gt;eg.&lt;/em&gt;&lt;span style=&quot;color:#222222&quot;&gt;http://myrc.in/recharge/complain?username=500011&amp;amp;pwd=123&amp;amp;mobile=980000000&amp;amp;amount=10&amp;amp;txid=123&amp;amp;message=refund&lt;/span&gt;&lt;span style=&quot;color:#222222&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;\n											&lt;p&gt;\n												&amp;nbsp;&lt;/p&gt;\n											&lt;div class=&quot;alert alert-info&quot;&gt;\n												&lt;strong&gt;Call Back URL&lt;/strong&gt;.&lt;/div&gt;\n											&lt;p&gt;\n												With the help of callback URL you will get auto status update.&lt;/p&gt;\n											&lt;p&gt;\n												This option allows you to automate the reversal of the dispute transactions&lt;/p&gt;\n											&lt;p&gt;\n												Whenever a dispute transaction is reversed we will trigger the URL configured by you along with the Operator&amp;nbsp;ID, Status and txid&amp;nbsp;&lt;/p&gt;\n											&lt;p&gt;\n												&lt;span style=&quot;color:#222222&quot;&gt;URL&lt;/span&gt;&lt;/p&gt;\n											&lt;div&gt;\n												&lt;div&gt;\n													www.yourdomain.com/yourfile?txid=YOUR ORDER ID&amp;amp;status=Success/Failure&amp;amp;opid=OPERATOR ID&lt;/div&gt;\n												&lt;div&gt;\n													&amp;nbsp;&lt;/div&gt;\n												&lt;div&gt;\n													Parameters&amp;rsquo;&lt;/div&gt;\n												&lt;div&gt;\n													&amp;nbsp;&lt;/div&gt;\n												&lt;div&gt;\n													txid=&amp;nbsp; Unique recharge id provided by you&amp;nbsp; on every recharge&lt;/div&gt;\n												&lt;div&gt;\n													status= Success / Failure&lt;/div&gt;\n												&lt;div&gt;\n													opid = Operator id&lt;/div&gt;\n											&lt;/div&gt;\n										&lt;/div&gt;\n										&lt;p&gt;\n											&amp;nbsp;&lt;/p&gt;\n										&lt;div class=&quot;alert alert-info&quot;&gt;\n											&lt;strong&gt;Operator Code&lt;/strong&gt;&lt;/div&gt;\n										&lt;table class=&quot;table table-bordered&quot;&gt;\n											&lt;tbody&gt;\n												&lt;tr&gt;\n													&lt;td&gt;\n														&lt;p&gt;\n															&lt;strong&gt;Operator&lt;/strong&gt;&lt;/p&gt;\n													&lt;/td&gt;\n													&lt;td&gt;\n														&lt;p&gt;\n															&lt;strong&gt;Code&lt;/strong&gt;&lt;/p&gt;\n													&lt;/td&gt;\n												&lt;/tr&gt;\n												&lt;tr&gt;\n													&lt;td&gt;\n														&lt;p&gt;\n															Aircel&lt;/p&gt;\n													&lt;/td&gt;\n													&lt;td&gt;\n														&lt;p&gt;\n															AIR&lt;/p&gt;\n						