									&lt;p&gt;\n															UNINOR - SPL&lt;/p&gt;\n													&lt;/td&gt;\n													&lt;td&gt;\n														&lt;p&gt;\n															US&lt;/p&gt;\n													&lt;/td&gt;\n												&lt;/tr&gt;\n												&lt;tr&gt;\n													&lt;td&gt;\n														&lt;p&gt;\n															VIDEOCON DTH TV&lt;/p&gt;\n													&lt;/td&gt;\n													&lt;td&gt;\n														&lt;p&gt;\n															VTV&lt;/p&gt;\n													&lt;/td&gt;\n												&lt;/tr&gt;\n												&lt;tr&gt;\n													&lt;td&gt;\n														&lt;p&gt;\n															VIRGIN - CDMA&lt;/p&gt;\n													&lt;/td&gt;\n													&lt;td&gt;\n														&lt;p&gt;\n															VC&lt;/p&gt;\n													&lt;/td&gt;\n												&lt;/tr&gt;\n												&lt;tr&gt;\n													&lt;td&gt;\n														&lt;p&gt;\n															VIRGIN - GSM&lt;/p&gt;\n													&lt;/td&gt;\n													&lt;td&gt;\n														&lt;p&gt;\n															VG&lt;/p&gt;\n													&lt;/td&gt;\n												&lt;/tr&gt;\n												&lt;tr&gt;\n													&lt;td&gt;\n														&lt;p&gt;\n															Vodafone&lt;/p&gt;\n													&lt;/td&gt;\n													&lt;td&gt;\n														&lt;p&gt;\n															V&lt;/p&gt;\n													&lt;/td&gt;\n												&lt;/tr&gt;\n											&lt;/tbody&gt;\n										&lt;/table&gt;\n										&lt;p&gt;\n											&amp;nbsp;&lt;/p&gt;\n										&lt;p&gt;\n											&lt;strong&gt;Operator Code for POSTPAID RECHARGE&lt;/strong&gt;&lt;/p&gt;\n										&lt;table class=&quot;table table-bordered&quot;&gt;\n											&lt;tbody&gt;\n												&lt;tr&gt;\n													&lt;td&gt;\n														&lt;p&gt;\n															&lt;strong&gt;Operator&lt;/strong&gt;&lt;/p&gt;\n													&lt;/td&gt;\n													&lt;td&gt;\n														&lt;p&gt;\n															&lt;strong&gt;Code&lt;/strong&gt;&lt;/p&gt;\n													&lt;/td&gt;\n												&lt;/tr&gt;\n											&lt;/tbody&gt;\n										&lt;/table&gt;\n									&lt;/div&gt;\n								&lt;/div&gt;\n							&lt;/div&gt;\n						&lt;/div&gt;\n						&lt;!-- Accordion Item End --&gt;&lt;!-- Accordion Item Start --&gt;&lt;!-- Accordion Item End --&gt;&lt;!-- Accordion Item Start --&gt;\n						&lt;div class=&quot;panel panel-default&quot;&gt;\n							&lt;div class=&quot;panel-heading&quot; role=&quot;tab&quot;&gt;\n								&lt;h4 class=&quot;panel-title&quot;&gt;\n									&amp;nbsp;&lt;/h4&gt;\n							&lt;/div&gt;\n							&lt;div class=&quot;panel-collapse collapse&quot; id=&quot;sharedTabQ5&quot; role=&quot;tabpanel&quot;&gt;\n								&lt;div class=&quot;panel-body&quot;&gt;\n									&lt;p&gt;\n										&amp;nbsp;&lt;/p&gt;\n								&lt;/div&gt;\n							&lt;/div&gt;\n						&lt;/div&gt;\n						&lt;!-- Accordion Item End --&gt;&lt;/div&gt;\n				&lt;/div&gt;\n				&lt;div class=&quot;tab-pane fade&quot; id=&quot;dmr&quot; role=&quot;tabpanel&quot;&gt;\n					&lt;div class=&quot;panel-group accordion&quot; id=&quot;accordion2&quot; role=&quot;tablist&quot;&gt;\n						&lt;!-- Accordian Item Start --&gt;\n						&lt;div class=&quot;panel panel-default active&quot;&gt;\n							&lt;div class=&quot;panel-heading&quot; role=&quot;tab&quot;&gt;\n								&lt;h4 class=&quot;panel-title&quot;&gt;\n									&lt;a data-parent=&quot;#accordion2&quot; data-toggle=&quot;collapse&quot; href=&quot;#vpsTabQ1&quot; role=&quot;button&quot;&gt;MONEY TRANSFER API DETAILS&lt;/a&gt;&lt;/h4&gt;\n							&lt;/div&gt;\n							&lt;div class=&quot;panel-collapse collapse in&quot; id=&quot;vpsTabQ1&quot; role=&quot;tabpanel&quot;&gt;\n								&lt;div class=&quot;panel-body&quot;&gt;\n									&lt;div class=&quot;table-responsive&quot;&gt;\n										&lt;p&gt;\n											&amp;nbsp;&lt;/p&gt;\n										&lt;h4&gt;\n											TRANSFER MONEY&lt;/h4&gt;\n										&lt;p&gt;\n											&amp;nbsp;&lt;/p&gt;\n										&lt;code&gt;http://myrc.in/money/api?username=500011&amp;amp;pwd=123&amp;amp;sender_mobile=980000000&amp;amp;mode=IMPS&amp;amp;ben_id=225&amp;amp;amount=10&amp;amp;orderid=466558&amp;amp;format=json &lt;/code&gt;&lt;br /&gt;\n										&lt;p&gt;\n											sender_mobile = SENDER MOBILE NUMBER&lt;br /&gt;\n											mode = PAYMENT MODE&lt;br /&gt;\n											ben_id = BENEFICIARY ID (YOU WILL GET WHEN YOU ADD BENEFICIARY)&lt;br /&gt;\n											amount = TRANSFER AMOUNT&lt;br /&gt;\n											orderid = THIS IS YOUR UNIQUE ORDER ID&lt;br /&gt;\n											format = JSON FORMAT&lt;/p&gt;\n										&lt;p&gt;\n											OUTPUT RESPONSE&lt;/p&gt;\n										&lt;p&gt;\n											&lt;code&gt;{&amp;quot;txid&amp;quot;:6546,&amp;quot;status&amp;quot;:200,&amp;quot;message&amp;quot;:&amp;quot;FUND TRASNFER SUCCESS.&amp;quot;,&amp;quot;beneficiaryName&amp;quot;:DEMO,&amp;quot;BeneficiaryID&amp;quot;:&amp;quot;225&amp;quot;,&amp;quot;amount&amp;quot;:&amp;quot;10&amp;quot;,&amp;quot;orderid&amp;quot;:&amp;quot;466558&amp;quot;}&lt;/code&gt;&lt;/p&gt;\n										&lt;p&gt;\n											if status 200 -&amp;gt; Fund successfully transferred , 201 -&amp;gt; Fund transfer request accepted, Other than 201 please follow message&lt;/p&gt;\n										&lt;p&gt;\n											&amp;nbsp;&lt;/p&gt;\n										&lt;h4&gt;\n											SENDER REGISTERATION&lt;/h4&gt;\n										&lt;p&gt;\n											&amp;nbsp;&lt;/p&gt;\n										&lt;code&gt;http://myrc.in/money/sender_registration?username=500011&amp;amp;pwd=123&amp;amp;name=etechdital&amp;amp;pincode=734010&amp;amp;sender_mobile=980000000 &lt;/code&gt;\n										&lt;p&gt;\n											&amp;nbsp;&lt;/p&gt;\n										&lt;h4&gt;\n											ADD BENEFICIARY&lt;/h4&gt;\n										&lt;p&gt;\n											&amp;nbsp;&lt;/p&gt;\n										&lt;code&gt;http://myrc.in/money/add_beneficiary?username=500011&amp;amp;pwd=123&amp;amp;sender_mobile=980000000&amp;amp;ben_name=RAHUL&amp;amp;ben_mobile=980000000&amp;amp;account_number=1000100&amp;amp;ifsc_code=SBIN0007745 &lt;/code&gt;\n										&lt;p&gt;\n											&amp;nbsp;&lt;/p&gt;\n										&lt;h4&gt;\n											VERIFY BENEFICIARY&lt;/h4&gt;\n										&lt;p&gt;\n											&amp;nbsp;&lt;/p&gt;\n										&lt;code&gt;http://myrc.in/money/verify_beneficiary?username=500011&amp;amp;pwd=123&amp;amp;sender_mobile=980000000&amp;amp;otp=123&amp;amp;ben_id=12365 &lt;/code&gt;\n										&lt;p&gt;\n											&amp;nbsp;&lt;/p&gt;\n										&lt;h4&gt;\n											SEARCH BENEFICIARY&lt;/h4&gt;\n										&lt;p&gt;\n											&amp;nbsp;&lt;/p&gt;\n										&lt;code&gt;http://myrc.in/money/search_beneficiary?username=500011&amp;amp;pwd=123&amp;amp;sender_mobile=980000000 &lt;/code&gt;&lt;/div&gt;\n								&lt;/div&gt;\n							&lt;/div&gt;\n						&lt;/div&gt;\n						&lt;!-- Accordian Item End --&gt;&lt;!-- Accordian Item Start --&gt;&lt;/div&gt;\n				&lt;/div&gt;\n			&lt;/div&gt;\n			&lt;!-- FAQ Content End --&gt;&lt;/div&gt;\n	&lt;/div&gt;\n&lt;/div&gt;\n&lt;!-- FAQ Area End --&gt;');
