INSERT INTO `plan_upgrade` (`id`, `plan`) VALUES
(1, '      \n&lt;style&gt;\n* {\n    box-sizing: border-box;\n}\n\n.columns {\n    float: left;\n    width: 33.3%;\n    padding: 8px;\n}\n\n.price {\n    list-style-type: none;\n    border: 1px solid #eee;\n    margin: 0;\n    padding: 0;\n    -webkit-transition: 0.3s;\n    transition: 0.3s;\n}\n\n.price:hover {\n    box-shadow: 0 8px 12px 0 rgba(0,0,0,0.2)\n}\n\n.price .header {\n    background-color: #111;\n    color: white;\n    font-size: 25px;\n}\n\n.price li {\n    border-bottom: 1px solid #eee;\n    padding: 20px;\n    text-align: center;\n}\n\n.price .grey {\n    background-color: #eee;\n    font-size: 20px;\n}\n\n.button {\n    background-color: #4CAF50;\n    border: none;\n    color: white;\n    padding: 10px 25px;\n    text-align: center;\n    text-decoration: none;\n    font-size: 18px;\n}\n\n@media only screen and (max-width: 600px) {\n    .columns {\n        width: 100%;\n    }\n}\n&lt;/style&gt;\n\n&lt;h2 style=&quot;text-align:center&quot;&gt;API Pricing and Commission Structure&lt;/h2&gt;\n&lt;p style=&quot;text-align:center&quot;&gt;To Activate Please click on Buy Now Button&lt;/p&gt;\n\n&lt;div class=&quot;columns&quot;&gt;\n  &lt;ul class=&quot;price&quot;&gt;\n    &lt;li class=&quot;header&quot;&gt;Free&lt;/li&gt;\n    &lt;li class=&quot;grey&quot;&gt;Rs  0.00 / year&lt;/li&gt;\n    &lt;li&gt;Jio 4%&lt;/li&gt;\n    &lt;li&gt;Telenor 3.5%&lt;/li&gt;\n    &lt;li&gt;Reliance 3.0%&lt;/li&gt;\n    &lt;li&gt;MTS 3.0%&lt;/li&gt;\n    &lt;li&gt;MTNL 2.5%&lt;/li&gt;\n    &lt;li&gt;Aircel 3.5%&lt;/li&gt;\n    &lt;li&gt;Idea 2.0%&lt;/li&gt;\n    &lt;li&gt;Docomo 3.5%&lt;/li&gt;\n    &lt;li&gt;Airtel 2.0%&lt;/li&gt;\n    &lt;li&gt;Vodafone 2.0%&lt;/li&gt;\n    &lt;li&gt;BSNL 3.0%&lt;/li&gt;\n\n    &lt;li class=&quot;grey&quot;&gt;&lt;a href=&quot;#&quot; class=&quot;button&quot;&gt;Sign Up&lt;/a&gt;&lt;/li&gt;\n  &lt;/ul&gt;\n&lt;/div&gt;\n\n&lt;div class=&quot;columns&quot;&gt;\n  &lt;ul class=&quot;price&quot;&gt;\n    &lt;li class=&quot;header&quot; style=&quot;background-color:#4CAF50&quot;&gt;Pro&lt;/li&gt;\n    &lt;li class=&quot;grey&quot;&gt;Rs &lt;del&gt;5000&lt;/del&gt; 2500 / year&lt;/li&gt;\n  &lt;li&gt;Jio 5%&lt;/li&gt;\n    &lt;li&gt;Telenor 4.5%&lt;/li&gt;\n    &lt;li&gt;Reliance 3.5%&lt;/li&gt;\n    &lt;li&gt;MTS 3.5%&lt;/li&gt;\n    &lt;li&gt;MTNL 3.0%&lt;/li&gt;\n    &lt;li&gt;Aircel 4.0%&lt;/li&gt;\n    &lt;li&gt;Idea 2.2%&lt;/li&gt;\n    &lt;li&gt;Docomo 4.0%&lt;/li&gt;\n    &lt;li&gt;Airtel 2.5%&lt;/li&gt;\n    &lt;li&gt;Vodafone 3.0%&lt;/li&gt;\n    &lt;li&gt;BSNL 3.5%&lt;/li&gt;\n    &lt;li class=&quot;grey&quot;&gt;&lt;a href=&quot;#&quot; class=&quot;button&quot;&gt;Sign Up&lt;/a&gt;&lt;/li&gt;\n  &lt;/ul&gt;\n&lt;/div&gt;\n\n&lt;div class=&quot;columns&quot;&gt;\n  &lt;ul class=&quot;price&quot;&gt;\n    &lt;li class=&quot;header&quot; &gt;Premium&lt;/li&gt;\n    &lt;li class=&quot;grey&quot;&gt;Rs 5,000 / One Time&lt;/li&gt;\n    &lt;li&gt;Jio 6%&lt;/li&gt;\n    &lt;li&gt;Telenor 5%&lt;/li&gt;\n    &lt;li&gt;Reliance 3.7%&lt;/li&gt;\n    &lt;li&gt;MTS 4.0%&lt;/li&gt;\n    &lt;li&gt;MTNL 3%&lt;/li&gt;\n    &lt;li&gt;Aircel 4.5%&lt;/li&gt;\n    &lt;li&gt;Idea 2.6%&lt;/li&gt;\n    &lt;li&gt;Docomo 4.25%&lt;/li&gt;\n    &lt;li&gt;Airtel 3.0%&lt;/li&gt;\n    &lt;li&gt;Vodafone 3.35%&lt;/li&gt;\n    &lt;li&gt;BSNL 4.0%&lt;/li&gt;\n    &lt;li class=&quot;grey&quot;&gt;&lt;a href=&quot;#&quot; class=&quot;button&quot;&gt;Sign Up&lt;/a&gt;&lt;/li&gt;\n  &lt;/ul&gt;\n&lt;/div&gt;\n        ');
